async function main() {
  const posts = JSON.parse(readFileSync(POSTS_FILE, 'utf-8'));
  let matched = 0;
  for (const post of posts) {
    if (COMMENTS[post.id]) {
      post.comment = COMMENTS[post.id];
      matched++;
      console.log(`✓ ${post.author.displayName}: ${COMMENTS[post.id].substring(0, 50)}...`);
    } else {
      post.comment = '';
      console.log(`✗ ${post.author.displayName}: no comment -- re-run "write comments" in Claude Code`);
    }
  }
  writeFileSync(POSTS_FILE, JSON.stringify(posts, null, 2));
  console.log(`\nDone. Matched ${matched}/${posts.length} comments.`);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
